# Width of the image used in every moving sprite (in pixels)
Stage.layer_background_width = 520;
Stage.layer_grass_width = 520;
Stage.layer_flowers_width = 520;
Stage.layer_clouds_width = 575;

# Horizontal speed of the moving sprites
Stage.layer_background_speed = 0.05;
Stage.layer_grass_speed = 0.15;
Stage.layer_flowers_speed = 7;
Stage.layer_clouds_speed = 0.6;

self.create_clone();
while True: 
    self.change_x(Stage.layer_grass_speed);
    if (self.x_position > Stage.layer_grass_width):
        self.set_x(-Stage.layer_grass_width);

self.set_x(-Stage.layer_grass_width);
